import styled from "styled-components";


export const BodyRegisterContainer= styled.div`
  
    width: 100%;
    height: 10vh;
    position:relative;
   
`

export const CardRegisterContainer = styled.div`
    top:0;
    left:0;
    width:25%;
    height:10rem;
    position: absolute;
    box-shadow: 5px 4px 6px rgba(0,0,0,0.25);

`
